export function guid() {
    const S4 = () => (((1 + Math.random()) * 0x10000) | 0).toString(16).substring(1)
    return (S4() + S4() + '-' + S4() + '-4' + S4().slice(0, 3) + '-' + S4() + '-' + S4() + S4() + S4()).toLowerCase()
}

export function isColorVisible(background: string, foreground: string) {
    const backgroundAsRgb = hexToRgb(background),
        foregroundAsRgb = hexToRgb(foreground),
        value = .77

    return (backgroundAsRgb.r + backgroundAsRgb.g + backgroundAsRgb.b) / (foregroundAsRgb.r + foregroundAsRgb.g + foregroundAsRgb.b) < value
}

export function getColor(red: string, green: string, blue: string) {
    return {
        r: parseInt(red, 16),
        g: parseInt(green, 16),
        b: parseInt(blue, 16)
    } as Color
}

export function hexToRgb(hex: string): Color {
    if (hex.length > 4) {
        const value = getHexValues(hex)
        if (value)
            return getColor(value[1], value[2], value[3])
    } else {
        const value = getShortHexValues(hex)
        if (value)
            return getColor(
                value[1] + value[1],
                value[2] + value[2],
                value[3] + value[3]
            )
    }

    return new Color()
}

export function isISOString(str: string) {
    return /\d{4}-[01]\d-[0-3]\dT[0-2]\d:[0-5]\d:[0-5]\d\.\d+/.test(str)
}

export function getHexValues(str: string) {
    return /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(str)
}

export function getShortHexValues(str: string) {
    return /^#?([a-f\d])([a-f\d])([a-f\d])$/i.exec(str)
}

export function applyAlpha(color: string, opacity: number) {
    function hexToRgb(hex: string) {
        const result = getHexValues(hex)
        return result ? getColor(result[1], result[2], result[3]) : new Color()
    }

    function rgbToHex(r: number, g: number, b: number) {
        function toHex(c: number) {
            let hex = c.toString(16)
            return hex.length == 1 ? '0' + hex : hex
        }

        return '#' + toHex(r) + toHex(g) + toHex(b)
    }

    const rgb = hexToRgb(color),
        bg = hexToRgb(Theme.canvasBackground)

    opacity /= 255

    const alpha = 1 - opacity

    return rgbToHex(
        Math.round((opacity * (rgb.r / 255) + (alpha * (bg.r / 255))) * 255),
        Math.round((opacity * (rgb.g / 255) + (alpha * (bg.g / 255))) * 255),
        Math.round((opacity * (rgb.b / 255) + (alpha * (bg.b / 255))) * 255)
    )
}

export function getRoundedValues(all: number[]) {
    if (!Array.isArray(all) || all.length === 0) {
        return []
    }

    const maxVal = Math.max(0, ...all)

    if (maxVal === 0) {
        return []
    }

    const targetTicks = 5
    const intervals = targetTicks - 1

    const rawStep = maxVal / intervals

    const magnitude = Math.pow(10, Math.floor(Math.log10(rawStep)))
    const normalizedStep = rawStep / magnitude

    let prettyNormalizedStep
    if (normalizedStep <= 1) {
        prettyNormalizedStep = 1
    } else if (normalizedStep <= 2) {
        prettyNormalizedStep = 2
    } else if (normalizedStep <= 2.5) {
        prettyNormalizedStep = 2.5
    } else if (normalizedStep <= 5) {
        prettyNormalizedStep = 5
    } else {
        prettyNormalizedStep = 10
    }

    const step = prettyNormalizedStep * magnitude

    const ticks = []
    for (let i = 0; i < targetTicks; i++) {
        ticks.push(Number((i * step).toFixed(12)))
    }

    return ticks
}

export function min(array: number[]) {
    let len = array.length
    let min = Infinity

    while (len--)
        min = array[len] < min ? array[len] : min

    return min
}

export function max(array: number[]) {
    let len = array.length
    let max = -Infinity

    while (len--)
        max = array[len] > max ? array[len] : max

    return max
}

export function parseNumber(value: string | null | number, decimalSeparator: string = '.') {
    const simplify = (v: string) => {
        return !v
            ? 0
            : +(v.replace(',', '')
                .replace('.', '')
                .replace('-', ''))
    }

    const removeExtraZeros = (v: number) => {
        while (v % 10 == 0 && v != 0)
            v /= 10
        return v
    }

    const countLeadingZeros = (v: string) => {
        let count = 0
        while (v.length > 0 && v.slice(0, 1) == '0') {
            v = v.slice(1)
            count++
        }
        return v.length == 0 || count == 0 ? 0 : count
    }

    const getDividerForFractional = (v: string) => {
        let trimmed = v

        while (trimmed.length > 0 && trimmed[0] == '0')
            trimmed = trimmed.slice(1)

        while (trimmed.length > 0 && trimmed[trimmed.length - 1] == '0')
            trimmed = trimmed.slice(0, trimmed.length - 1)

        return Math.pow(10, countLeadingZeros(v) + trimmed.length)
    }

    if (!value)
        return 0

    if (typeof value == 'number')
        return value

    let split = value.split(decimalSeparator),
        left = simplify(split[0]),
        right = split.length > 1
            ? removeExtraZeros(simplify(split[1])) / getDividerForFractional(split[1])
            : 0

    if (split.length > 1 && split[1].length > 9) {
        const slice = split[1].slice(0, 8)

        right = removeExtraZeros(simplify(slice)) / getDividerForFractional(slice)
    }

    const negative = value.slice(0, 1) == '-' ? -1 : 1

    const result = (left + right / (right >= 1 ? Math.pow(10, `${right}`.length) : 1))
        * negative

    const localeString = result.toLocaleString()

    if (value.startsWith(localeString))
        return result
    else if (value.startsWith(localeString.replace(',', '!')
        .replace('.', ',')
        .replace('!', '.')))
        return result
    else if (value.startsWith(result.toString()))
        return result
    else if (value.startsWith(result.toString().replace(',', '!')
        .replace('.', ',')
        .replace('!', '.')))
        return result

    return parseNumber(value, ',')
}